<?php use Dilemma\Views; $participants = array_column($debate['participants'], null, 'user_id'); ?>
<section class="argument-section" id="arguments"><div class="section-heading"><h2><?= $t('arguments') ?></h2><span><?= (int) ceil((int) $debate['message_count'] / 2) ?> <?= $t('rounds') ?></span></div>
<?php if (!$debate['messages']): ?><p class="empty-message"><?= $t('no_arguments') ?></p><?php else: ?><div class="argument-timeline"><?php foreach ($debate['messages'] as $message): $author = $participants[$message['author_id']]; ?>
<details class="argument side-<?= (int) $author['side'] ?>" id="argument-<?= $e($message['id']) ?>" data-argument="<?= $e($message['id']) ?>"><summary><div class="argument-meta"><span class="argument-number"><?= (int) $message['ordinal'] ?></span><strong><?= $author['account_status'] === 'deleted' ? $t('deleted_participant') : $e($author['alias']) ?></strong><time datetime="<?= $e($message['created_at']) ?>Z"><?= $e(Views::date($message['created_at'])) ?></time></div><p class="argument-excerpt user-text"><?= $message['excerpt'] !== '' ? $e($message['excerpt']) . ((int) $message['body_length'] > 650 ? '…' : '') : $t('removed_content') ?></p><span class="expand-label"><?= $t('full_argument') ?> <span aria-hidden="true">+</span></span></summary><div class="argument-body" aria-live="polite"></div>
<?php if ($member && $member['left_at'] === null && $message['author_id'] === $user['id'] && $debate['status'] !== 'archived'): ?><details class="amend-form"><summary><?= $t('clarification') ?></summary><?= Views::form('/api/arguments/' . $message['id'] . '/amend') ?><?= Views::hidden('revision', $debate['revision']) ?><?= Views::area('clarification', 'clarification') ?><?= Views::area('sources_text', 'sources_input', '', false, 4000) ?><?= Views::submit('amend') ?></form></details><?php endif; ?></details>
<?php endforeach; ?></div><?= Views::pagination($debate['page'], $debate['pages']) ?><?php endif; ?></section>
<?php if ($debate['workflow']['can_publish']): ?><details class="compose disclosure"><summary><?= $t('manual_post') ?></summary><p><?= $t('manual_help') ?></p><?= Views::form('/api/debates/' . $id . '/argument', 'reload', 'data-draft="argument-' . $e($id) . '"') ?><?= Views::hidden('revision', $debate['revision']) ?><?= Views::area('body', 'body', '', true, 20000) ?><label class="field"><span><?= $t('reply_to') ?></span><select name="reply_to_id"><option value=""><?= $t('no_reply') ?></option><?php foreach ($debate['messages'] as $message): ?><option value="<?= $e($message['id']) ?>">#<?= (int) $message['ordinal'] ?> · <?= $e(mb_substr($message['excerpt'], 0, 70)) ?></option><?php endforeach; ?></select></label><?= Views::area('sources_text', 'sources_input', '', false, 4000) ?><?= Views::submit('post') ?></form></details><?php endif; ?>
<?php if ((int) $debate['message_count'] > 0 || array_filter($debate['positions'], static fn ($position) => $position['value'] !== null)): ?>
<details class="positions-panel disclosure" id="positions"><summary><?= $t('positions') ?></summary><p class="muted"><?= $t('positions_help') ?> <?= !$member ? $t('position_private_help') : '' ?></p>
<?php if (!$debate['positions']): ?><p><?= $t('no_positions') ?></p><?php else: ?><div class="position-chart"><div class="scale-labels"><span><?= $e($debate['left_label']) ?> · 0</span><span><?= $e($debate['right_label']) ?> · 100</span></div><?php foreach ($debate['positions'] as $position): $owner = $participants[$position['user_id']]; ?><div class="position-observation side-<?= (int) $owner['side'] ?>"><div><strong><?= $owner['account_status'] === 'deleted' ? $t('deleted_participant') : $e($owner['alias']) ?></strong><time><?= $e(Views::date($position['created_at'])) ?></time></div><meter min="0" max="100" value="<?= $position['value'] === null ? 0 : (int) $position['value'] ?>" <?= $position['value'] === null ? 'hidden' : '' ?> aria-label="<?= $e($owner['alias']) ?>"><?= (int) $position['value'] ?></meter><span><?= $position['value'] === null ? $t('not_given') : (int) $position['value'] ?></span><?php if ($position['note'] !== ''): ?><p class="user-text"><?= $e($position['note']) ?></p><?php endif; ?></div><?php endforeach; ?></div><?= Views::pagination($debate['position_page'], $debate['position_pages'], 'positions_page') ?><?php endif; ?></details>
<?php endif; ?>
<?php if ((int) $debate['message_count'] > 0): ?>
<details class="history-panel" data-history="<?= $e($id) ?>"><summary><?= $t('history') ?></summary><label><span class="visually-hidden"><?= $t('all_events') ?></span><select data-event-filter><option value=""><?= $t('all_events') ?></option><?php foreach (['argument_published', 'agent_needs_human', 'agent_reconsidering', 'seat_opened', 'joined', 'position_recorded', 'white_flag', 'paused', 'resumed'] as $kind): ?><option value="<?= $kind ?>"><?= $t($kind) ?></option><?php endforeach; ?></select></label><ol class="event-list"></ol><button type="button" class="button secondary" data-more-events><?= $t('load_more') ?></button><p class="form-feedback" role="status"></p></details>
<?php endif; ?>
